INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m25731$nota-0084$m25731$, $m25732$Training and Racing with a Power Meter.pdf$m25732$, $m25733$220$m25733$, $m25734$Acute Training Load (ATL)... is calculated as an exponentially weighted moving average of daily TSS values, with the default time constant set to seven days. (In effect, what this means is that your ATL is primarily a function of the training that you have done in the past two weeks.)$m25734$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m25735$nota-0084$m25735$, $m25736$nota-0062$m25736$, $m25737$pre-requisito$m25737$, $m25738$ATL é calculado a partir do TSS diário definido na nota-0062$m25738$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m25739$nota-0084$m25739$, $m25740$nota-0083$m25740$, $m25741$complementa$m25741$, $m25742$junto com CTL (nota-0083), forma a base do TSB (Training Stress Balance)$m25742$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m25743$nota-0085$m25743$, $m25744$Training and Racing with a Power Meter.pdf$m25744$, $m25745$220$m25745$, $m25746$Training Stress Balance (a term coined by cycling coach Dave Harris) is the difference between chronic and acute training loads: TSB = CTL – ATL.$m25746$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m25747$nota-0085$m25747$, $m25748$Training and Racing with a Power Meter.pdf$m25748$, $m25749$223$m25749$, $m25750$Form = Fitness + Freshness. A rider can be fit at the end of the Tour de France, but he will be very tired, and not on form... Only the correct balance of fitness and freshness will create form.$m25750$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m25751$nota-0085$m25751$, $m25752$Training and Racing with a Power Meter.pdf$m25752$, $m25753$227$m25753$, $m25754$If your TSB is a positive number, this indicates more freshness... When your TSB is a negative number, this indicates more fatigue.$m25754$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m25755$nota-0085$m25755$, $m25756$nota-0083$m25756$, $m25757$pre-requisito$m25757$, $m25758$TSB usa o CTL definido na nota-0083$m25758$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m25759$nota-0085$m25759$, $m25760$nota-0084$m25760$, $m25761$pre-requisito$m25761$, $m25762$TSB usa o ATL definido na nota-0084$m25762$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m25763$nota-0085$m25763$, $m25764$nota-0091$m25764$, $m25765$complementa$m25765$, $m25766$nota-0091 define que o TSB ideal varia por duração/tipo de evento — corrige a referência antiga desta nota (que apontava erroneamente para nota-0090, sobre ramp rate de CTL, assunto não relacionado)$m25766$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m25767$nota-0087$m25767$, $m25768$Training and Racing with a Power Meter.pdf$m25768$, $m25769$226$m25769$, $m25770$power at shorter durations (e.g., at/near Pmax) seems to be especially dependent upon an individual's 'freshness,' whereas power at much longer durations (e.g., at/near FTP) seems to be much less so... may therefore benefit from using a longer ATL time constant (say, 10 or even 14 days instead of the default of 7 days).$m25770$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m25771$nota-0087$m25771$, $m25772$Training and Racing with a Power Meter.pdf$m25772$, $m25773$226$m25773$, $m25774$athletes who are aiming for much longer races (e.g., a mountain-bike marathon) may benefit from using a shorter ATL time constant (say, 3–5 days instead of the default 7), which will require that they maintain their training until closer to their event to prevent TSB from going too positive.$m25774$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m25775$nota-0087$m25775$, $m25776$nota-0084$m25776$, $m25777$pre-requisito$m25777$, $m25778$ajusta a constante de tempo padrão do ATL definida na nota-0084$m25778$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m25779$nota-0087$m25779$, $m25780$nota-0086$m25780$, $m25781$complementa$m25781$, $m25782$outro fator (idade) que também influencia a constante de tempo ideal do ATL$m25782$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m25783$nota-0091$m25783$, $m25784$Training and Racing with a Power Meter.pdf$m25784$, $m25785$232$m25785$, $m25786$personal bests for power in all time periods have occurred at a wide range of TSBs, from –30 to +30... The majority of personal bests occurred with TSBs between –5 and +15.$m25786$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m25787$nota-0091$m25787$, $m25788$Training and Racing with a Power Meter.pdf$m25788$, $m25789$233$m25789$, $m25790$personal bests for time periods of less than 5 minutes occurred when the TSB was even more on the positive side of the scale... in short, heavily anaerobic events (track, BMX, short hill climbs), it is best to be very well rested.$m25790$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m25791$nota-0091$m25791$, $m25792$Training and Racing with a Power Meter.pdf$m25792$, $m25793$233$m25793$, $m25794$In the personal bests from time periods of 5 minutes or more, there is a swing back to the center... a nice bell curve distribution for TSBs from –10 to +25... an athlete competing in a longer event... should not taper or rest too much beforehand, as this could mean missing that peak window.$m25794$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m25795$nota-0091$m25795$, $m25796$nota-0085$m25796$, $m25797$pre-requisito$m25797$, $m25798$usa o TSB definido na nota-0085$m25798$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m25799$nota-0094$m25799$, $m25800$Training and Racing with a Power Meter.pdf$m25800$, $m25801$239$m25801$, $m25802$Matt's third-best 20-minute wattage occurred at the end of March, immediately after another steep increase in CTL at a ramp rate of 12 TSS per day for 2 weeks. Although the TSB was still negative at this point, it was clearly climbing positively. It is important to recognize that TSB does not necessarily need to be a positive number in order to create a peak performance; it just needs to be climbing to a positive number.$m25802$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m25803$nota-0094$m25803$, $m25804$nota-0085$m25804$, $m25805$complementa$m25805$, $m25806$nuance importante sobre como interpretar o TSB definido na nota-0085$m25806$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m25807$nota-0102$m25807$, $m25808$Training and Racing with a Power Meter.pdf$m25808$, $m25809$282$m25809$, $m25810$The WAC (Williams, Allen, Coggan) score chart is a tool that assigns the rider a score for all time durations against the world's best and then adjusts the score to account for age. It's essentially a variation on the Power Profile chart that captures how a rider compares against the world's best both in the pro ranks and in their age category. Bill's peak WAC score is a 74 against his peers at 22:48, which means he performs at 74 percent of the world champion's best wattage for that same time duration.$m25810$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m25811$nota-0102$m25811$, $m25812$nota-0032$m25812$, $m25813$alternativa-a$m25813$, $m25814$variação do Power Profile (nota-0032) que usa como referência os melhores do mundo ajustados por idade, em vez das categorias fixas do Power Profile clássico$m25814$)
